1	#!/usr/bin/env node
2	
3	/**
4	 * QCET PreToolUse Ownership Guard
5	 *
6	 * Enforces architectural lifecycle invariants:
7	 * 1. Intercepts Write and Edit tool invocations.
8	 * 2. Prohibits read-only agents (recon, skeptic, researcher, verifiers, reviewers) from modifying files.
9	 * 3. Resolves active shard ownership (owns, antiOwns) from state files or environment variables.
10	 * 4. Blocks out-of-scope modifications and antiOwns violations with actionable remediation reasons.
11	 * 5. Fail-safes to exit 0 outside executor workflows (interactive sessions, unmapped agents, non-Write tools).
12	 */
13	
14	const fs = require('fs');
15	const path = require('path');
16	
17	// -----------------------------------------------------------------------------
18	// PROTOCOL CONSTANTS & EXIT CODES
19	// -----------------------------------------------------------------------------
20	const EXIT_ALLOW = 0;
21	const EXIT_BLOCK = 2;
22	
23	// Known read-only agent types or roles
24	const READ_ONLY_AGENTS = new Set([
25	  'qcet-recon',
26	  'qcet-skeptic',
27	  'qcet-researcher',
28	  'verifier',
29	  'verify',
30	  'data-reviewer',
31	  'security-reviewer',
32	  'ux-reviewer',
33	  'recon',
34	  'skeptic',
35	  'researcher',
36	  'reviewer',
37	  'auditor'
38	]);
39	
40	// -----------------------------------------------------------------------------
41	// DETERMINISTIC PATH & GLOB UTILITIES
42	// -----------------------------------------------------------------------------
43	const {
44	  normalizePath,
45	  globToRegex,
46	  matchesOwnership,
47	  toRepoRelativePath,
48	} = require('./path-matcher.cjs');
49	
50	// -----------------------------------------------------------------------------
51	// READ-ONLY AGENT DETECTION
52	// -----------------------------------------------------------------------------
53	function isReadOnlyAgent(agentType, agentId, agentRole, subagentLabel) {
54	  const candidates = [agentType, agentId, agentRole, subagentLabel]
55	    .filter(Boolean)
56	    .map((s) => String(s).toLowerCase().trim());
57	
58	  for (const c of candidates) {
59	    if (READ_ONLY_AGENTS.has(c)) {
60	      return true;
61	    }
62	    // Pattern match for specialized read-only roles
63	    if (
64	      /(?:^|[-_:])(recon|skeptic|researcher|verifier|verify|reviewer|review|audit)(?:[-_:]|$)/i.test(c) ||
65	      /\b(recon|skeptic|researcher|verifier|verify|reviewer|review|audit)\b/i.test(c)
66	    ) {
67	      // Exempt utility and synchronizer agents from read-only categorization
68	      if (c.includes('recorder') || c.includes('synchronizer') || c.includes('telemetry')) {
69	        continue;
70	      }
71	      return true;
72	    }
73	  }
74	  return false;
75	}
76	
77	// -----------------------------------------------------------------------------
78	// SHARD MAPPING RESOLUTION
79	// -----------------------------------------------------------------------------
80	function extractCandidateShardIds(agentId, subagentLabel) {
81	  const candidates = new Set();
82	  for (const raw of [agentId, subagentLabel].filter(Boolean)) {
83	    const s = String(raw).trim();
84	    candidates.add(s);
85	
86	    // Strip leading prefix like builder:, repair:, implement:, etc.
87	    const withoutPrefix = s.replace(/^(builder|repair|implement|reconcile|attempt)[:\-_]/i, '');
88	    candidates.add(withoutPrefix);
89	
90	    // Strip trailing suffix like :repair, :repair-1, :attempt-1, :1
91	    const withoutSuffix = withoutPrefix.replace(/[:\-_](repair(-\d+)?|implement|attempt(-\d+)?|\d+)$/i, '');
92	    candidates.add(withoutSuffix);
93	
94	    // Match colon/hyphen separated segments
95	    if (s.includes(':')) {
96	      const parts = s.split(':');
97	      for (const p of parts) {
98	        if (p && !['builder', 'repair', 'attempt', 'implement', 'reconcile'].includes(p.toLowerCase())) {
99	          candidates.add(p);
100	        }
101	      }
102	    }
103	  }
104	  return [...candidates].filter(Boolean);
105	}
106	
107	function resolveActiveShard(agentId, agentType, subagentLabel) {
108	  // 1. Check explicit environment variables
109	  if (process.env.QCET_CURRENT_SHARD) {
110	    try {
111	      const parsed = JSON.parse(process.env.QCET_CURRENT_SHARD);
112	      if (parsed && typeof parsed === 'object') return parsed;
113	    } catch (_) {}
114	  }
115	
116	  if (process.env.QCET_SHARD_OWNS) {
117	    let owns = [];
118	    try {
119	      owns = JSON.parse(process.env.QCET_SHARD_OWNS);
120	    } catch (_) {
121	      owns = process.env.QCET_SHARD_OWNS.split(',').map((s) => s.trim()).filter(Boolean);
122	    }
123	    let antiOwns = [];
124	    if (process.env.QCET_SHARD_ANTI_OWNS) {
125	      try {
126	        antiOwns = JSON.parse(process.env.QCET_SHARD_ANTI_OWNS);
127	      } catch (_) {
128	        antiOwns = process.env.QCET_SHARD_ANTI_OWNS.split(',').map((s) => s.trim()).filter(Boolean);
129	      }
130	    }
131	    return {
132	      id: process.env.QCET_SHARD_ID || 'env-configured-shard',
133	      owns,
134	      antiOwns
135	    };
136	  }
137	
138	  // 2. Candidate state file locations (prioritize run-scoped files)
