92	  // ---------------------------------------------------------------------------
93	  console.log('\n[benchmark] === PHASE B: Running Optimized B1 ===');
94	  const b1Start = Date.now();
95	  const b1Telemetry = new ExecutionTelemetry('benchmark-run-B1', { repoRoot });
96	  b1Telemetry.startPhase('execution');
